arguments.command:
python -c "
import parse
p = parse.Parser('''
            letters: {:w}
            non-letters: {:W}
            whitespace: \"{:s}\"
            non-whitespace: \\t{:S}\\n
            digits: {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
            ISO 8601 e.g. {:ti}
            RFC2822 e.g. {:te}
            Global e.g. {:tg}
            US e.g. {:ta}
            ctime() e.g. {:tc}
            HTTP e.g. {:th}
            time: {:tt}
            final value: {}
        ''')
print('Expression:', p._expression[:500])
" 2>&1 | grep -v SyntaxWarning
